import json
import os

BASE = '/root/autodl-tmp/distrib_canary_collapse/results'

experiments = {
    'null': [
        f'{BASE}/alpha_sweep/a000_s42/analysis/5method_leadlag.json',
        f'{BASE}/alpha_sweep/a000_s43/analysis/5method_leadlag.json',
        f'{BASE}/alpha_sweep/a000_s44/analysis/5method_leadlag.json',
        f'{BASE}/alpha_sweep/a000_s46_fp32/analysis/5method_leadlag.json',
        f'{BASE}/alpha_sweep/a000_s48_fp32/analysis/5method_leadlag.json',
    ],
    'a050': [
        f'{BASE}/alpha_sweep/a050_s42/analysis/5method_leadlag.json',
        f'{BASE}/alpha_sweep/a050_s43/analysis/5method_leadlag.json',
        f'{BASE}/alpha_sweep/a050_s44/analysis/5method_leadlag.json',
    ],
    'a075': [
        f'{BASE}/alpha_sweep/a075_s42/analysis/5method_leadlag.json',
        f'{BASE}/alpha_sweep/a075_s43/analysis/5method_leadlag.json',
        f'{BASE}/alpha_sweep/a075_s44/analysis/5method_leadlag.json',
    ],
}

M5 = ['naive_xcorr', 'diff_xcorr', 'threshold_onset', 'perm_granger', 'ty_granger']
M4 = ['diff_xcorr', 'threshold_onset', 'perm_granger', 'ty_granger']

def extract_fwd_sig(pair):
    fwd = pair['forward']
    sig = {}
    # NaiveXCorr: significant AND peak_lag < 0 (D111 direction filter C009)
    nx = fwd.get('naive_xcorr', {})
    sig['naive_xcorr'] = bool(nx.get('significant', False) and nx.get('peak_lag', 0) < 0)
    # DiffXCorr: significant_fdr AND peak_lag < 0
    dx = fwd.get('diff_xcorr', {})
    sig['diff_xcorr'] = bool(dx.get('significant_fdr', dx.get('significant', False)) and dx.get('peak_lag', 0) < 0)
    # Threshold: significant (true_3sigma_d105, already directional)
    th = fwd.get('threshold_onset', {})
    sig['threshold_onset'] = bool(th.get('significant', False))
    # PermG: significant_fdr
    pg = fwd.get('perm_granger', {})
    sig['perm_granger'] = bool(pg.get('significant_fdr', pg.get('significant', False)))
    # TY: significant
    ty = fwd.get('ty_granger', {})
    sig['ty_granger'] = bool(ty.get('significant', False))
    return sig

def fleiss_kappa(matrix, methods):
    n = len(matrix)
    if n == 0:
        return float('nan')
    N = len(methods)
    if N <= 1:
        return float('nan')
    P_i_sum = 0.0
    total_pos = 0
    for pair in matrix:
        k = sum(1 for m in methods if pair[m])
        total_pos += k
        P_i = (k*(k-1) + (N-k)*(N-k-1)) / (N*(N-1))
        P_i_sum += P_i
    P_bar = P_i_sum / n
    p_pos = total_pos / (n * N)
    p_neg = 1 - p_pos
    P_e = p_pos**2 + p_neg**2
    if P_e >= 1.0:
        return 1.0
    return (P_bar - P_e) / (1 - P_e)

def pairwise_cohen_kappa(matrix, m1, m2):
    n = len(matrix)
    if n == 0:
        return float('nan')
    a = sum(1 for p in matrix if p[m1] == p[m2])
    p_o = a / n
    p1 = sum(1 for p in matrix if p[m1]) / n
    p2 = sum(1 for p in matrix if p[m2]) / n
    p_e = p1*p2 + (1-p1)*(1-p2)
    if p_e >= 1.0:
        return 1.0
    return (p_o - p_e) / (1 - p_e)

all_5 = []
all_4 = []
per_condition = {}
per_pair_detail = {}

for cond, files in experiments.items():
    c5, c4 = [], []
    details = []
    for fp in files:
        if not os.path.exists(fp):
            print(f"WARN: missing {fp}", flush=True)
            continue
        with open(fp) as f:
            data = json.load(f)
        seed = data['meta'].get('seed', '?')
        for pair in data['pairs']:
            sig = extract_fwd_sig(pair)
            p5 = {m: sig[m] for m in M5}
            p4 = {m: sig[m] for m in M4}
            c5.append(p5); all_5.append(p5)
            c4.append(p4); all_4.append(p4)
            details.append({
                'seed': seed,
                'pair': f"{pair['canary']}->{pair['downstream']}",
                **{m: int(sig[m]) for m in M5},
                'votes_5': sum(sig[m] for m in M5),
                'votes_4': sum(sig[m] for m in M4),
            })

    n = len(c5)
    k5 = fleiss_kappa(c5, M5)
    k4 = fleiss_kappa(c4, M4)

    k2of4 = sum(1 for p in c4 if sum(p.values()) >= 2)
    k3of4 = sum(1 for p in c4 if sum(p.values()) >= 3)
    k3of5 = sum(1 for p in c5 if sum(p.values()) >= 3)
    k4of5 = sum(1 for p in c5 if sum(p.values()) >= 4)

    mr5 = {m: sum(1 for p in c5 if p[m]) for m in M5}
    mr4 = {m: sum(1 for p in c4 if p[m]) for m in M4}

    per_condition[cond] = {
        'n_pairs': n,
        'kappa_5method': round(k5, 4),
        'kappa_4method': round(k4, 4),
        'K_ge_2_of_4': f'{k2of4}/{n} = {100*k2of4/n:.1f}%' if n else 'N/A',
        'K_ge_3_of_4': f'{k3of4}/{n} = {100*k3of4/n:.1f}%' if n else 'N/A',
        'K_ge_3_of_5': f'{k3of5}/{n} = {100*k3of5/n:.1f}%' if n else 'N/A',
        'K_ge_4_of_5': f'{k4of5}/{n} = {100*k4of5/n:.1f}%' if n else 'N/A',
        'per_method_sig_rate': {m: f'{mr5[m]}/{n} = {100*mr5[m]/n:.1f}%' for m in M5} if n else {},
    }
    per_pair_detail[cond] = details

# Pooled kappa
pk5 = fleiss_kappa(all_5, M5)
pk4 = fleiss_kappa(all_4, M4)

# Pairwise Cohen's kappa (pooled across all conditions)
pw_5 = {}
for i, m1 in enumerate(M5):
    for m2 in M5[i+1:]:
        pw_5[f'{m1}_vs_{m2}'] = round(pairwise_cohen_kappa(all_5, m1, m2), 4)
pw_4 = {}
for i, m1 in enumerate(M4):
    for m2 in M4[i+1:]:
        pw_4[f'{m1}_vs_{m2}'] = round(pairwise_cohen_kappa(all_4, m1, m2), 4)

output = {
    'description': '4-method kappa analysis (excluding NaiveXCor). Methods: PermG(FDR), DiffXCorr(FDR+lag<0), Threshold(3sigma_d105), TY. Direction filter C009 applied.',
    'experiments': {
        'null': 'a000_s42/s43/s44/s46_fp32/s48_fp32 (Pythia-410M, T=10)',
        'a050': 'a050_s42/s43/s44',
        'a075': 'a075_s42/s43/s44',
    },
    'kappa_5method_pooled': round(pk5, 4),
    'kappa_4method_pooled': round(pk4, 4),
    'kappa_improvement': f'{pk4 - pk5:+.4f}',
    'per_condition': per_condition,
    'voting_4method': {
        'K_ge_2_of_4': {
            'FPR_alpha0': per_condition['null']['K_ge_2_of_4'],
            'TPR_alpha050': per_condition['a050']['K_ge_2_of_4'],
            'TPR_alpha075': per_condition['a075']['K_ge_2_of_4'],
        },
        'K_ge_3_of_4': {
            'FPR_alpha0': per_condition['null']['K_ge_3_of_4'],
            'TPR_alpha050': per_condition['a050']['K_ge_3_of_4'],
            'TPR_alpha075': per_condition['a075']['K_ge_3_of_4'],
        },
    },
    'comparison_with_5method': {
        'K_ge_3_of_5_FPR': per_condition['null']['K_ge_3_of_5'],
        'K_ge_3_of_4_FPR': per_condition['null']['K_ge_3_of_4'],
        'K_ge_3_of_5_TPR_a075': per_condition['a075']['K_ge_3_of_5'],
        'K_ge_3_of_4_TPR_a075': per_condition['a075']['K_ge_3_of_4'],
    },
    'pairwise_cohen_kappa_5method': pw_5,
    'pairwise_cohen_kappa_4method': pw_4,
    'per_pair_voting_matrix': per_pair_detail,
    'total_pairs_analyzed': len(all_5),
}

print(json.dumps(output, indent=2))
