def extract_sig(pair):
    fwd = pair['forward']
    sig = {}
    nx = fwd.get('naive_xcorr', {})
    sig['naive_xcorr'] = bool(nx.get('significant', False) and nx.get('peak_lag', 0) < 0)
    dx = fwd.get('diff_xcorr', {})
    sig['diff_xcorr'] = bool(dx.get('significant_fdr', dx.get('significant', False)) and dx.get('peak_lag', 0) < 0)
    sig['threshold_onset'] = bool(fwd.get('threshold_onset', {}).get('significant', False))
    pg = fwd.get('perm_granger', {})
    sig['perm_granger'] = bool(pg.get('significant_fdr', pg.get('significant', False)))
    sig['ty_granger'] = bool(fwd.get('ty_granger', {}).get('significant', False))
    return sig

def fleiss_kappa(matrix, methods):
    n = len(matrix)
    if n == 0: return float('nan')
    N = len(methods)
    if N <= 1: return float('nan')
    P_i_sum = 0.0; total_pos = 0
    for pair in matrix:
        k = sum(1 for m in methods if pair[m])
        total_pos += k
        P_i = (k*(k-1) + (N-k)*(N-k-1)) / (N*(N-1))
        P_i_sum += P_i
    P_bar = P_i_sum / n
    p_pos = total_pos / (n * N)
    P_e = p_pos**2 + (1-p_pos)**2
    if P_e >= 1.0: return 1.0
    return (P_bar - P_e) / (1 - P_e)

def pairwise_cohen(matrix, m1, m2):
    n = len(matrix)
    if n == 0: return float('nan')
    a = sum(1 for p in matrix if p[m1] == p[m2])
    p_o = a / n
    p1 = sum(1 for p in matrix if p[m1]) / n
    p2 = sum(1 for p in matrix if p[m2]) / n
    p_e = p1*p2 + (1-p1)*(1-p2)
    if p_e >= 1.0: return 1.0
    return (p_o - p_e) / (1 - p_e)

output = {}
all_5, all_4 = [], []
pair_details = {}

for cond, files in experiments.items():
    c5, c4, details = [], [], []
    for fp in files:
        if not os.path.exists(fp): continue
        with open(fp) as f: data = json.load(fp)
        seed = data['meta'].get('seed', '?')
        for p in data['pairs']:
            sig = extract_sig(p)
            p5 = {m: sig[m] for m in M5}
            p4 = {m: sig[m] for m in M4}
            c5.append(p5); c4.append(p4)
            all_5.append(p5); all_4.append(p4)
            details.append({
                'seed': seed,
                'pair': f"{p['canary']}->{p['downstream']}",
                **{m: int(sig[m]) for m in M5},
                'K5': sum(sig[m] for m in M5),
                'K4': sum(sig[m] for m in M4),
            })

    n = len(c5)
    if n == 0: continue
    k5 = fleiss_kappa(c5, M5)
    k4 = fleiss_kappa(c4, M4)

    k2of4 = sum(1 for p in c4 if sum(p.values()) >= 2)
    k3of4 = sum(1 for p in c4 if sum(p.values()) >= 3)
    k4of4 = sum(1 for p in c4 if sum(p.values()) >= 4)
    k3of5 = sum(1 for p in c5 if sum(p.values()) >= 3)
    k4of5 = sum(1 for p in c5 if sum(p.values()) >= 4)
    mr5 = {m: sum(1 for p in c5 if p[m]) for m in M5}

    output[cond] = {
        'n_pairs': n,
        'fleiss_kappa_5method': round(k5, 4),
        'fleiss_kappa_4method': round(k4, 4),
        'per_method_sig_rate': {m: {'count': mr5[m], 'rate': f'{100*mr5[m]/n:.1f}%'} for m in M5},
