    ref_5 = [{m: d[m] for m in M5} for d in pair_details['a100_gpt2m']]
    ref_4 = [{m: d[m] for m in M4} for d in pair_details['a100_gpt2m']]
    pw5 = {}
    for i, m1 in enumerate(M5):
